import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    f = [0] + [int(x) for x in data[1:n+1]]

    def get_fk(k):
        res = list(range(n + 1))
        for _ in range(k):
            new_res = [0] * (n + 1)
            for i in range(1, n + 1):
                new_res[i] = f[res[i]]
            res = new_res
        return res

    k = 1
    while True:
        fk = get_fk(k)
        is_idempotent = True
        for x in range(1, n + 1):
            if fk[fk[x]] != fk[x]:
                is_idempotent = False
                break
        if is_idempotent:
            print(k)
            return
        k += 1

if __name__ == "__main__":
    main()
